const job = $json.body.job || {};
const pricing = $json.body.pricing || {};
const scheduling = $json.body.scheduling || {};
const emailType = $json.body.email_type || "client";
const clientName = $json.body.client_name || "(not provided)";
const clientEmail = $json.body.client_email || "";

let instructions;
if (emailType === "operations") {
  const reason = job.urgency === "high" ? "HIGH URGENCY" : "Estimate exceeds $300";
  instructions = "Write an internal notification email for the operations team about a handyman job that needs manual handling.\n"
    + "Reason: " + reason + ".\n"
    + "Client: " + clientName + " (" + clientEmail + ").\n"
    + "Summarize the job, pricing, and proposed schedule. The team should review and contact the client.\n"
    + "Use a professional internal tone.";
} else {
  instructions = "Write a professional confirmation email for a handyman service client.\n"
    + "IMPORTANT: Start the email with \"Hi " + clientName + ",\" — you MUST use this exact name in the greeting.\n"
    + "Summarize the service, address, estimated cost, and proposed time slots.\n"
    + "End with clear next steps (reply to confirm a time slot).\n"
    + "Use a warm, professional tone.";
}

const prompt = "IMPORTANT:\n"
  + "- Output ONLY valid JSON.\n"
  + "- Do NOT use markdown.\n"
  + "- Do NOT use code fences.\n"
  + "- Do NOT add explanations.\n"
  + "- The entire response must start with { and end with }.\n\n"
  + instructions + "\n\n"
  + "Return ONLY JSON:\n"
  + '{ "subject": "", "message": "" }\n\n'
  + "The \"message\" field should contain the full email body as plain text.\n\n"
  + "Job:\n" + JSON.stringify(job) + "\n\n"
  + "Pricing:\n" + JSON.stringify(pricing) + "\n\n"
  + "Scheduling:\n" + JSON.stringify(scheduling);

return [{
  requestBody: {
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { temperature: 0.3 }
  }
}];

const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || "";
const cleaned = raw
  .replace(/```json\s*/i, "")
  .replace(/```\s*$/i, "")
  .trim();
let obj;
try {
  obj = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Comms agent output not valid JSON. Raw: " + raw);
}
return [{
  subject: obj.subject || "Handyman Service Update",
  message: obj.message || ""
}];
